package com.ecommerce.entity;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import lombok.ToString;
import org.hibernate.annotations.CreationTimestamp;

import java.time.Instant;
import java.util.UUID;

/**
 * Application-level user profile.
 *
 * IMPORTANT — Identity design:
 *   Supabase Auth owns authentication (auth.users table).
 *   This entity represents the application profile in public.users.
 *
 *   The id field MUST match the Supabase Auth UUID (auth.users.id).
 *   It is NOT auto-generated by Hibernate — it is provided externally.
 *
 *   In Stage 05, a PostgreSQL trigger on auth.users will automatically
 *   create the corresponding public.users row with the matching UUID.
 *
 *   Do NOT change the id generation strategy without considering Stage 05.
 */
@Entity
@Table(
        name = "users",
        uniqueConstraints = {
                @UniqueConstraint(name = "uk_users_email", columnNames = "email")
        }
)
@Getter
@Setter
@NoArgsConstructor
@ToString(exclude = {}) // Safe — no collection fields on User to exclude
public class User {

    /**
     * UUID provided by Supabase Auth — NOT auto-generated by Hibernate.
     * This will be set equal to auth.users.id in Stage 05.
     */
    @Id
    @Column(columnDefinition = "uuid", updatable = false, nullable = false)
    private UUID id;

    @Column(nullable = false, unique = true, length = 255)
    private String email;

    @Column(length = 100)
    private String fullName;

    @Column(length = 20)
    private String phone;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private UserRole role = UserRole.ROLE_USER;

    @Column(nullable = false)
    private boolean enabled = true;

    @CreationTimestamp
    @Column(nullable = false, updatable = false)
    private Instant createdAt;
}
